{"command":"cd logs; python3 - <<'EOF'
import re,datetime,collections
def gw_lines():
    with open('gateway.log') as f:
        for line in f:
            m=re.match(r'(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) \+0200 "(.*)" (\d{3}) req=([0-9a-f]+) upstream=(\w+) (\d+)ms',line)
            if m:
                d,mo,y,H,M,S,path,status,rid,up,ms=m.groups()
                dt=datetime.datetime(int(y),datetime.datetime.strptime(mo,'%b').month,int(d),int(H),int(M),int(S))-datetime.timedelta(hours=2)
                yield dt,status,rid,path,int(ms)
gw=list(gw_lines())
w=[r for r in gw if r[1]=='502' and datetime.datetime(2026,10,29,6,55)<=r[0]<=datetime.datetime(2026,10,29,7,35)]
print("502s 06:55-07:35:",len(w))
for r in w[:20]: print(r[0].isoformat(),r[2],r[3],r[4])
print("...last few")
for r in w[-5:]: print(r[0].isoformat(),r[2],r[3],r[4])
# non-502 in same window? count
allw=[r for r in gw if datetime.datetime(2026,10,29,6,55)<=r[0]<=datetime.datetime(2026,10,29,7,35)]
print("total reqs in window",len(allw))
EOF","description":"Examine 502s around the change window"}

