{"command":"cd logs; python3 - <<'EOF'
import re,gzip,collections,datetime
gw=[]
for line in open('gateway.log'):
    m=re.match(r'(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) \+0200 "(\S+) (\S+)" (\d{3}) req=([0-9a-f]+)',line)
    if not m: continue
    d,mo,y,H,M,S,meth,path,st,rid=m.groups()
    dt=datetime.datetime(int(y),datetime.datetime.strptime(mo,'%b').month,int(d),int(H),int(M),int(S))-datetime.timedelta(hours=2)
    gw.append((dt,st,rid,path))
ck=collections.Counter(); errs=[]
for src in (open('checkout.log'),open('checkout.log.1'),gzip.open('checkout.log.2.gz','rt')):
    for line in src:
        m=re.match(r'^(\S+Z) (INFO|ERROR|WARN) (w\d+) req=([0-9a-f]+) (GET|POST) (\S+) -> (\d+) ?(.*)$',line.strip())
        if m:
            ck[m.group(4)]+=1
            if m.group(2)=='ERROR': errs.append((m.group(1),m.group(4),m.group(8)))
print("ck unique",len(ck),"dups",sum(1 for v in ck.values() if v>1),"errors",len(errs))
pool=[e for e in errs if e[2].startswith('db pool')]
print("pool",len(pool),"first",min(pool)[0],"last",max(pool)[0],"all size=4?",all('size=4' in e[2] for e in pool))
poolids={e[1] for e in pool}
gw502={r[2]:r for r in gw if r[1]=='502'}
print("pool ids with gw502:",len(poolids & set(gw502)),"missing:",len(poolids-set(gw502)))
print("pool ids whose gw status !=502:",[ (rid,gw502.get(rid)) for rid in list(poolids)[:0]])
win=[r for r in gw if r[1]=='502' and datetime.datetime(2026,10,29,7,31,10,409000)<=r[0]<=datetime.datetime(2026,10,29,14,19,58,649000)]
print("gw502 in pool window:",len(win),"pool-attributable:",sum(1 for r in win if r[2] in poolids))
print("first 2 pool gateway lines:",[(r[0].isoformat(),r[2]) for r in sorted(gw) if r[2] in poolids][:2])
print("earliest 502s 07:00-07:32 and their checkout msg:")
for rid in [r[2] for r in sorted(gw) if r[1]=='502' and datetime.datetime(2026,10,29,7,0)<=r[0]<datetime.datetime(2026,10,29,7,32)]:
    print(" ",rid,[e[2][:45] for e in errs if e[1]==rid])
EOF","description":"Re-run verification with fixed filter"}

